BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Completeness of information provided to auditor
(1, 'Written Representations', 'Mercer & Associates is completing the audit of Bridgeport Industries for the year ended December 31, 2025. The engagement partner drafts the management representation letter and asks which required representation addresses the completeness of information provided. Under AU-C 580, management should represent that it has provided the auditor with:', '["Only the financial data specifically requested during fieldwork", "All information except items deemed immaterial by management", "All relevant information and access as agreed upon in the terms of the engagement", "A summary of significant transactions selected by the controller"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that it has provided the auditor with all relevant information and access as agreed upon in the engagement letter terms. This covers records, documentation, and personnel access. Unlike choice A, the representation is not limited to items specifically requested — it encompasses all information relevant to the financial statements and the conduct of the audit.', 'medium', 2),

-- Q2: medium / L3 — Internal control responsibility representation
(1, 'Written Representations', 'During the 2025 audit of Lakewood Dynamics, the CFO questions why the management representation letter includes language about internal controls when no material weaknesses were identified. The engagement partner at Hargrove & Klein explains that under AU-C 580, this representation is required because:', '["Internal control representations are only required when deficiencies are found during the audit", "Management is responsible for the design, implementation, and maintenance of internal control relevant to financial reporting", "The auditor requires management to certify that no control deficiencies exist anywhere in the entity", "Internal control language is optional and included only at the auditor''s discretion"]'::jsonb, 1, 'AU-C 580.12 requires management to acknowledge responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements. This representation is required regardless of whether deficiencies were identified. Unlike choice A, which incorrectly conditions the requirement on finding deficiencies, management''s responsibility for internal control exists independently of audit findings.', 'medium', 3),

-- Q3: easy / L1 — Form of written representations
(1, 'Written Representations', 'In what form should written representations from management be provided to the auditor under AU-C 580?', '["A signed written letter addressed to the auditor", "An oral confirmation recorded in the audit workpapers", "An email summary without a formal signature block", "A verbal acknowledgment at the closing conference"]'::jsonb, 0, 'AU-C 580.06 defines written representations as written statements by management provided to the auditor to confirm certain matters or support other audit evidence. The representations must be in a formal written letter, typically on entity letterhead and signed by appropriate management. Unlike choices B and D, oral confirmations do not satisfy the requirement regardless of whether they are documented in the workpapers.', 'easy', 1),

-- Q4: medium / L3 — Accounting policy change representation
(1, 'Written Representations', 'Redstone Manufacturing changed its inventory costing method from FIFO to weighted-average cost during 2025. The engagement team at Caldwell & Price adds specific language to the representation letter. Under AU-C 580, this additional representation should address whether management believes:', '["The prior-period statements should be retroactively restated to weighted-average cost", "The change will increase net income by at least 5 percent in the current period", "The auditor approved the accounting change before it was implemented", "The change in accounting policy is appropriate under the applicable financial reporting framework"]'::jsonb, 3, 'AU-C 580.12 requires management to represent that it believes the selection of accounting policies is appropriate. When a policy change occurs, management should represent that the new policy is appropriate under the applicable framework. Unlike choice C, the auditor does not approve accounting changes — that is management''s decision, and the representation confirms management''s own assessment of appropriateness.', 'medium', 3),

-- Q5: medium / L3 — Restricted access to records and personnel
(1, 'Written Representations', 'During the 2025 audit of Ashton Holdings, management informs the engagement team at Whitmore & Associates that board minutes from two executive sessions are confidential and cannot be shared. The auditor should evaluate this restriction because written representations under AU-C 580 require management to confirm that:', '["Board minutes are excluded from the scope of the audit engagement", "Management has provided the auditor with access to all information relevant to the audit", "Only financial records are covered by the representation letter", "The auditor may waive access to governance documents at management''s request"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that it has provided the auditor with all information relevant to the preparation and fair presentation of the financial statements and access to all persons within the entity. Restricting access to board minutes contradicts this representation. Unlike choice A, board minutes are not excluded from the audit scope — they are part of the governance documentation the auditor needs to review.', 'medium', 3),

-- Q6: medium / L2 — Compliance with laws and regulations
(1, 'Written Representations', 'Glenfield Pharmaceuticals operates in a heavily regulated industry. The engagement partner at Dunbar & Associates is finalizing the 2025 representation letter and considers what compliance-related language to include. Under AU-C 580, management should represent that it has disclosed to the auditor:', '["Only violations that resulted in fines exceeding $10,000 during the audit period", "That the entity has never been subject to any regulatory investigation", "All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements", "That outside legal counsel has certified full compliance with all applicable laws"]'::jsonb, 2, 'AU-C 580.12 requires management to represent that it has disclosed all known actual or possible noncompliance with laws and regulations whose effects should be considered when preparing the financial statements. Unlike choice A, the representation is not limited by a dollar threshold — it covers all known or suspected noncompliance relevant to the financial statements regardless of the fine amount.', 'medium', 2),

-- Q7: medium / L2 — Group audit component management representations
(1, 'Written Representations', 'Sterling Industries has a subsidiary, Apex Components, whose financial statements are audited by a component auditor. The group engagement partner at Prescott & Dunn is determining what written representations to obtain for the consolidated audit. Under AU-C 600, the group engagement team should obtain written representations from:', '["Component management regarding matters relevant to the group financial statements", "Only the parent company''s management since consolidated statements are the parent''s responsibility", "The component auditor rather than component management directly", "Neither party because the subsidiary''s separate audit is already sufficient"]'::jsonb, 0, 'AU-C 600.41 requires the group engagement team to obtain written representations from group management. Additionally, AU-C 580 principles extend to obtaining representations from component management about matters relevant to the group financial statements. Unlike choice B, relying solely on the parent''s representations would leave a gap in evidence about subsidiary-specific matters that affect the consolidated statements.', 'medium', 2),

-- Q8: medium / L3 — Side agreements and oral commitments
(1, 'Written Representations', 'While auditing Crestline Distributors for 2025, the engagement team at Farrell & Bowen discovers through inquiry that the CEO has an oral agreement with a key supplier providing extended 120-day payment terms not reflected in the financial statements. The auditor should ensure the representation letter addresses:', '["Only formal written contracts executed during the current audit period", "Matters limited to items that are already recorded in the general ledger", "That management bears no responsibility for disclosing oral arrangements", "All significant arrangements, including oral agreements, that could affect the financial statements"]'::jsonb, 3, 'AU-C 580.11-12 requires management to represent that it has provided all relevant information and that the financial statements are complete. Oral side agreements affecting payment terms may require recognition or disclosure. Unlike choice A, the representation letter should encompass all arrangements — written and oral — that could have a material effect on the financial statements, not just formal written contracts.', 'medium', 3),

-- Q9: hard / L4 — Contradictory evidence vs. management representation
(1, 'Written Representations', 'During the 2025 audit of Northfield Corp., management provides a written representation stating that all litigation has been disclosed. However, the attorney''s confirmation letter reveals a pending $4.5 million product liability claim not disclosed by management. The engagement partner at Wentworth & Hayes must evaluate the effect of this contradiction on the audit. The auditor''s most appropriate response is to:', '["Accept the representation letter as sufficient because it is a formal document signed by management", "Reconsider the reliability of management''s representations overall and evaluate the effect on other audit areas", "Withdraw from the engagement immediately without performing any further investigation or procedures", "Disregard the attorney''s letter because management representations take precedence over external evidence"]'::jsonb, 1, 'AU-C 580.17 requires the auditor to reconsider the reliability of representations when contradictory evidence exists. A material contradiction between the representation letter and the attorney''s confirmation raises doubt about all representations. Unlike choice A, the formal nature of the letter does not make it sufficient when direct contradictory evidence exists — the auditor must evaluate the broader implications for the audit.', 'hard', 4),

-- Q10: hard / L4 — Going concern representation and auditor evaluation
(1, 'Written Representations', 'Pacific Ventures reported $8.2 million in recurring operating losses and has a $12 million loan maturing in six months with no refinancing commitment. Management''s 2025 representation letter asserts the entity is a going concern and includes a turnaround plan projecting $3 million in new revenue from an unexecuted contract. The engagement partner at Thornton & Reed should:', '["Accept the going concern representation because management is best positioned to assess entity viability", "Disclaim an opinion solely because the entity has reported significant recurring operating losses", "Evaluate whether management''s plans are feasible and whether the representation is supported by sufficient evidence", "Require management to remove the going concern representation entirely from the letter"]'::jsonb, 2, 'AU-C 580.16 requires the auditor to evaluate whether written representations are consistent with other audit evidence. Under AU-C 570, the auditor must evaluate management''s plans for dealing with going concern conditions. An unexecuted contract does not constitute sufficient evidence to support feasibility. Unlike choice A, simply accepting the representation without corroborating evidence is insufficient when substantial doubt indicators exist.', 'hard', 4),

-- Q11: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'To whom should the management representation letter be addressed under AU-C 580?', '["The auditor, typically the engagement partner or audit firm", "The entity''s board of directors or audit committee", "The Securities and Exchange Commission or relevant regulator", "The entity''s external legal counsel handling audit matters"]'::jsonb, 0, 'AU-C 580.10 specifies that the management representation letter should be addressed to the auditor. The letter is a direct communication from management to the engagement partner or audit firm confirming matters discussed during the audit. Unlike choice B, it is not addressed to the board or audit committee — those parties may receive separate communications but are not the intended recipients under AU-C 580.', 'easy', 1),

-- Q12: medium / L2 — Title to assets and liens
(1, 'Written Representations', 'The audit team at Crawford & Sinclair is completing the 2025 audit of Ironclad Manufacturing, which owns $14 million in equipment. The engagement partner reviews the representation letter to ensure it includes a representation about assets. Under AU-C 580, management should represent that:', '["All equipment is fully depreciated and carries no remaining useful life or residual value", "The entity carries adequate insurance coverage on all of its tangible fixed assets", "No assets have been acquired using any form of related-party financing arrangements", "The entity has satisfactory title to all owned assets and has disclosed all liens and encumbrances"]'::jsonb, 3, 'AU-C 580.12 requires management to represent that the entity has satisfactory title to all owned assets and that all liens, pledges, or other encumbrances on assets have been disclosed. This representation addresses the rights and obligations assertion. Unlike choice B, insurance coverage — while relevant to the audit — is not the specific asset-related representation required by AU-C 580.', 'medium', 2),

-- Q13: hard / L3 — Off-balance-sheet arrangements
(1, 'Written Representations', 'Pinnacle Holdings has guaranteed $6 million in debt for an unconsolidated variable interest entity and has a $2.5 million purchase commitment with a below-market pricing clause. During the 2025 audit, the engagement partner at Langford & Kirk determines that neither arrangement appears in the financial statements or notes. The most appropriate action regarding the representation letter is to:', '["Accept management''s omission because off-balance-sheet items are not covered by AU-C 580 requirements", "Include the items in the representation letter only if they individually exceed overall materiality", "Ensure management represents that all guarantees, commitments, and off-balance-sheet arrangements requiring disclosure have been identified", "Request that management remove any references to off-balance-sheet items from the representation letter"]'::jsonb, 2, 'AU-C 580.11-12 requires management to represent that the financial statements are complete, which encompasses all items requiring recognition or disclosure under the applicable framework. Off-balance-sheet guarantees and purchase commitments may require disclosure under ASC 460 and ASC 440. Unlike choice A, the completeness representation in AU-C 580 covers all financial statement elements including off-balance-sheet arrangements.', 'hard', 3),

-- Q14: hard / L4 — Accounting estimates and assumptions
(1, 'Written Representations', 'Brookfield Insurance uses a discounted cash flow model to estimate its $45 million claim liability reserve. The model relies on projected loss development factors, discount rates, and expected settlement timing — all involving significant judgment. The engagement team at Pendleton & Shaw reviews the representation letter for adequate coverage of estimates. Under AU-C 580, management should represent that:', '["The auditor has approved all assumptions used in developing the estimate", "The methods, data, and significant assumptions used in making accounting estimates are reasonable in the context of the applicable framework", "Management warrants the estimate will not require any adjustment in future reporting periods", "Only externally sourced data used in the valuation model requires a written representation"]'::jsonb, 1, 'AU-C 580.12 requires management to represent that it believes significant assumptions used in making accounting estimates are reasonable. AU-C 540 further emphasizes evaluating methods, data, and assumptions. Unlike choice A, the auditor does not approve assumptions — that is management''s responsibility. Representations about estimates cover all significant inputs including internally developed data, not just external sources.', 'hard', 4),

-- Q15: medium / L2 — Additional auditor-requested representations
(1, 'Written Representations', 'The engagement partner at Whitfield & Hayes is auditing Oceanic Shipping, which operates container vessels under complex charter agreements across multiple jurisdictions. Beyond the standard representations required by AU-C 580, the auditor considers requesting additional representations. Additional written representations may be requested when:', '["The entity operates in an industry with specialized transactions or regulatory requirements affecting the financial statements", "The auditor wants to reduce the total number of substantive procedures to be performed during fieldwork", "Management voluntarily offers to expand the representation letter beyond the required content", "The total engagement fee for the audit exceeds a predetermined materiality threshold amount"]'::jsonb, 0, 'AU-C 580.14 permits the auditor to request additional written representations beyond those specifically required when the circumstances of the engagement warrant them. Specialized industries or complex transactions may necessitate entity-specific representations. Unlike choice B, additional representations do not reduce the need for substantive procedures — they supplement, rather than replace, other audit evidence.', 'medium', 2),

-- Q16: easy / L1 — Representations do not substitute for other procedures
(1, 'Written Representations', 'Under AU-C 580, can written representations from management serve as a substitute for other audit procedures the auditor determines are necessary?', '["Yes, if management''s representations are signed by both the CEO and the CFO", "Yes, provided the representations address all relevant financial statement assertions", "No, but representations are required only when other audit evidence is unavailable", "No, representations complement but do not replace other procedures the auditor considers necessary"]'::jsonb, 3, 'AU-C 580.05 states that written representations are an important source of audit evidence but do not provide sufficient appropriate audit evidence on their own about any of the matters with which they deal. Unlike choices A and B, even when signed by the highest levels of management or addressing all assertions, representations cannot substitute for substantive testing or other required procedures.', 'easy', 1),

-- Q17: hard / L4 — Debt covenant noncompliance representation
(1, 'Written Representations', 'Greystone Properties has a $28 million term loan requiring a debt-to-equity ratio below 3:1, measured quarterly. At December 31, 2025, Greystone''s ratio is 3.4:1, triggering a technical default. Management has not disclosed the covenant violation and argues the lender informally agreed to waive it. The engagement partner at Beckett & Lane should:', '["Obtain a representation that all noncompliance with contractual agreements has been disclosed and evaluate whether the waiver requires documentation or disclosure", "Accept management''s oral explanation of the informal waiver without requesting any further action or documentation from management", "Require the lender to provide a separate representation letter addressed directly to the auditor confirming the informal waiver", "Omit the covenant matter from the representation letter since it was resolved informally before the report date"]'::jsonb, 0, 'AU-C 580.12 requires management to represent that all noncompliance with contractual agreements has been disclosed. Under ASC 470-10, a covenant violation at the balance sheet date generally requires reclassification of debt as current unless a formal waiver is obtained. Unlike choice B, the auditor cannot simply accept an oral explanation of an informal waiver — the representation and supporting documentation must be evaluated.', 'hard', 4),

-- Q18: hard / L4 — Omitted pledged assets in representation letter
(1, 'Written Representations', 'During the 2025 audit of Vanguard Electronics, the auditor at Morrison & Tate discovers through bank confirmation replies that $3.2 million in accounts receivable are pledged as collateral for a line of credit. The management representation letter makes no mention of pledged assets. The engagement partner should evaluate this omission because it:', '["Is immaterial since the receivables still belong to the entity and remain on the balance sheet", "Only matters if the pledged receivables are individually past due or considered uncollectible", "Indicates that management''s representations may be incomplete, requiring the auditor to reconsider overall reliability", "Should be addressed by the lending bank rather than included in the management representation letter"]'::jsonb, 2, 'AU-C 580.17 requires the auditor to reconsider the reliability of management representations when evidence contradicts them. The bank confirmation reveals pledged assets that management failed to disclose, directly contradicting the completeness of the representation letter. Unlike choice A, the fact that receivables remain on the balance sheet does not eliminate the need to disclose liens and encumbrances under AU-C 580.12.', 'hard', 4),

-- Q19: medium / L3 — Plans and intentions affecting carrying value
(1, 'Written Representations', 'Keystone Apparel holds $7 million in excess inventory from a discontinued product line. Management''s representation letter states it intends to sell the inventory through a liquidation channel within six months at 40 percent of cost. The engagement team at Fletcher & Cole must determine whether this representation adequately supports the inventory''s carrying value. The auditor should:', '["Accept the representation at face value since management is responsible for inventory valuation decisions", "Evaluate whether management''s plans are feasible and supported by corroborating evidence such as liquidation agreements", "Require management to write down the inventory to zero regardless of its actual liquidation potential", "Exclude the discontinued inventory from the scope of the representation letter entirely"]'::jsonb, 1, 'AU-C 580.12 requires representations about the reasonableness of significant assumptions, including management''s plans and intentions that may affect carrying values. However, AU-C 580.05 makes clear that representations alone are not sufficient evidence. Unlike choice A, the auditor must evaluate whether management''s liquidation plan is feasible by examining corroborating evidence, not simply accept the representation.', 'medium', 3),

-- Q20: easy / L1 — Subsequent events representation content
(1, 'Written Representations', 'What should the management representation letter state regarding events occurring after the balance sheet date?', '["That no events of any kind occurred after the balance sheet date", "That only Type I recognized subsequent events have been evaluated by management", "That subsequent events are outside the scope of the written representation letter", "That all subsequent events requiring adjustment or disclosure have been properly reflected"]'::jsonb, 3, 'AU-C 580.12 requires management to represent that all events occurring subsequent to the date of the financial statements and for which the applicable framework requires adjustment or disclosure have been adjusted or disclosed. Unlike choice B, the representation covers both Type I and Type II events — it is not limited to recognized events only, and subsequent events cannot be excluded from the letter.', 'easy', 1),

-- Q21: easy / L1 — Unrecorded liabilities representation
(1, 'Written Representations', 'Under AU-C 580, what must management represent regarding the completeness of liabilities in the financial statements?', '["That all liabilities and contingencies required to be recognized or disclosed have been properly addressed", "That the entity has absolutely no liabilities beyond those currently listed on the balance sheet", "That only liabilities independently confirmed by third parties are required to be disclosed", "That contingent liabilities are excluded from the scope of the representation letter"]'::jsonb, 0, 'AU-C 580.12 requires management to represent that all liabilities, both actual and contingent, that are required to be recognized or disclosed under the applicable framework have been properly recorded or disclosed. Unlike choice D, contingent liabilities are specifically included within the scope of required representations and cannot be excluded from the letter.', 'easy', 1),

-- Q22: medium / L2 — Completeness of related party identification
(1, 'Written Representations', 'The engagement team at Donovan & Associates completes the 2025 audit of Silverline Corp. and reviews the representation letter''s related party disclosures. Management lists three related entities but omits a company owned by the CEO''s spouse that has $800,000 in transactions with Silverline. Under AU-C 580, the representation letter should confirm that management has:', '["Disclosed only related parties with transactions exceeding the materiality threshold", "Identified and disclosed all related parties and all related party relationships and transactions", "Limited related party disclosures to entities sharing common direct ownership interests", "Excluded family members of officers from the scope of related party identification"]'::jsonb, 1, 'AU-C 580.12 requires management to represent that it has disclosed the identity of all related parties and all related party relationships and transactions. Under AU-C 550, related parties include entities controlled by key management personnel and their close family members. Unlike choice C, which limits disclosure to common ownership, the CEO''s spouse''s company qualifies as a related party regardless of direct ownership overlap.', 'medium', 2),

-- Q23: easy / L1 — Oral vs. written representations
(1, 'Written Representations', 'If management provides oral assurances about a financial statement matter during the audit, do those assurances satisfy the written representation requirements of AU-C 580?', '["Yes, if the auditor documents the oral assurance in the audit workpapers", "Yes, provided at least two members of management are present during the discussion", "No, oral representations do not satisfy the requirement for written representations under AU-C 580", "No, unless the oral assurances are independently confirmed by external legal counsel"]'::jsonb, 2, 'AU-C 580.06 requires that representations be in written form. Oral assurances, even if documented in the auditor''s workpapers, do not satisfy the standard''s requirement for a written representation letter. Unlike choice A, documenting oral statements in the workpapers does not convert them into written representations — a formal signed letter from management is required.', 'easy', 1),

-- Q24: medium / L3 — Initial audit representation differences
(1, 'Written Representations', 'Hartwell & Associates is engaged to perform the initial audit of Crescent Technologies for the year ended December 31, 2025, with comparative 2024 financial statements. The predecessor auditor audited the 2024 statements. The engagement partner considers what representations are needed for this initial engagement. In an initial audit with comparative statements, the representation letter should:', '["Cover only the current-year financial statements since the predecessor audited the prior year", "Exclude representations about opening balances because the predecessor provided a clean opinion", "Address only transactions occurring after the date the engagement letter was signed", "Cover all periods referred to in the auditor''s report, including prior-period comparative figures"]'::jsonb, 3, 'AU-C 580.10 requires that the representation letter cover all periods referred to in the auditor''s report. In an initial audit with comparative financial statements, the current auditor must obtain representations covering both years. Unlike choice A, the predecessor''s prior opinion does not relieve the current auditor of the need to obtain representations about prior-period amounts as presented in the comparative statements.', 'medium', 3),

-- Q25: medium / L3 — Prior-period comparative statements
(1, 'Written Representations', 'Kingsley Corp. presents comparative financial statements for 2025 and 2024, both audited by Palmer & Webb. During the 2025 audit, the engagement partner discovers that management revised the 2024 depreciation schedule after the prior-year audit was completed but did not disclose the revision. The auditor should ensure the representation letter:', '["Addresses the completeness and accuracy of revisions to prior-period amounts in the comparative statements", "Covers only the current year since the 2024 statements were already audited and reported on", "Excludes prior-period matters unless they individually exceed current-year materiality levels", "Defers all prior-period representation requirements to the predecessor auditor for that year"]'::jsonb, 0, 'AU-C 580.10 requires representations to cover all periods referred to in the auditor''s report. When comparative statements are presented, the auditor must obtain representations about prior-period amounts as currently presented. Unlike choice B, a previously issued opinion does not eliminate the need for current representations about the comparative figures — especially when undisclosed revisions have been made.', 'medium', 3),

-- Q26: easy / L2 — Availability of minutes and records
(1, 'Written Representations', 'During the 2025 audit of Beacon Industries, the engagement team at Sullivan & Drake asks management to confirm access to governance records. Under AU-C 580, management should represent that it has made available to the auditor:', '["Only financial records stored in the accounting department during the audit period", "All minutes of meetings of shareholders and directors, as well as all financial records and related data", "Board minutes only for meetings at which financial matters were specifically discussed", "Records limited to those that were created during the current fiscal year only"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that it has made available all information relevant to the audit, including minutes of shareholder and board meetings and financial records. Unlike choice A, the representation is not limited to the accounting department''s records — it encompasses all governance documentation, meeting minutes, and financial data regardless of where they are maintained.', 'easy', 2),

-- Q27: easy / L1 — Period covered by the representation letter
(1, 'Written Representations', 'What periods must the management representation letter cover under AU-C 580?', '["Only the most recent fiscal quarter of the audit period", "The current year and the two preceding fiscal years", "Only the period from the engagement letter date to the report date", "All financial statement periods referred to in the auditor''s report"]'::jsonb, 3, 'AU-C 580.10 specifies that the written representations must cover all financial statement periods referred to in the auditor''s report. If the auditor reports on two years of comparative financial statements, the representation letter must cover both years. Unlike choice C, the coverage period is defined by the financial statement periods reported on, not by the dates of the engagement letter.', 'easy', 1),

-- Q28: easy / L1 — Financial reporting framework representation
(1, 'Written Representations', 'Under AU-C 580, what must management represent regarding the applicable financial reporting framework?', '["That the auditor selected the appropriate reporting framework for the entity", "That the entity may omit disclosures required by the framework if they are immaterial", "That the financial statements are prepared in accordance with the applicable financial reporting framework", "That the framework was approved by the entity''s external legal counsel before adoption"]'::jsonb, 2, 'AU-C 580.12 requires management to acknowledge responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. Unlike choice A, the selection of the framework is management''s responsibility, not the auditor''s. The concept of materiality does not permit management to omit disclosures specifically required by the framework.', 'easy', 1),

-- Q29: medium / L2 — Fair value measurement representations
(1, 'Written Representations', 'Meridian Capital holds $18 million in Level 3 financial instruments measured at fair value using internally developed pricing models. The engagement partner at Garrett & Associates is drafting the 2025 representation letter. For fair value measurements with significant unobservable inputs, the auditor should obtain representations that:', '["Management believes the measurement methods, assumptions, and data used in determining fair values are appropriate under the framework", "Only Level 1 and Level 2 fair value measurements require written representations from management", "The entity''s external valuation specialist assumes all responsibility for Level 3 fair value valuations", "Fair value representations are not required when the amounts are disclosed rather than recognized in the statements"]'::jsonb, 0, 'AU-C 580.12 requires management to represent that the methods, data, and significant assumptions used in making accounting estimates — including fair value measurements — are reasonable. Level 3 measurements with unobservable inputs involve the most judgment and therefore require clear representations. Unlike choice B, all fair value levels require representations, and unlike choice C, management retains responsibility even when using external specialists.', 'medium', 2),

-- Q30: medium / L2 — Nonadjusting events disclosed in representation
(1, 'Written Representations', 'On February 15, 2026, three weeks before the auditor''s report date, Atlas Corp. announces a $22 million acquisition of a competitor. The transaction occurred after the December 31, 2025 balance sheet date and does not affect year-end account balances. The engagement partner at Howell & Grant considers the representation letter. Management should represent that this nonadjusting subsequent event has been:', '["Recognized as an adjustment to the December 31, 2025 financial statements", "Properly disclosed in the notes to the financial statements as required by the framework", "Excluded from both the financial statements and the representation letter entirely", "Reported only in the 2026 interim financial statements rather than the 2025 annual report"]'::jsonb, 1, 'AU-C 580.12 requires management to represent that subsequent events requiring disclosure have been properly disclosed. Under AU-C 560 and ASC 855, a significant post-balance-sheet acquisition is a Type II nonadjusting event that requires note disclosure but not financial statement adjustment. Unlike choice A, nonadjusting events are disclosed in the notes rather than recognized as adjustments to the financial statements.', 'medium', 2)
;

COMMIT;
